import { useCallback, useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { api } from './api';
import { RibbonStrip } from '../../components/ui/RibbonStrip';

type Company = { legalName: string; tradeName: string; cnpj: string; phone: string; industry: string; city: string; state: string; website: string | null; description: string | null; publicSlug: string; role: 'OWNER' | 'RECRUITER' | 'ANALYST' };
type Listing = { id: number; kind: 'job' | 'course'; title: string; area: string; description: string; requirements: string; location: string; modality: string; url: string; contactEmail: string; salary: string | null; contractType: string | null; workSchedule: string | null; workload: string | null; prerequisites: string | null; benefits: string | null; coursePrice: string | null; certificate: string | null; expiresAt: string | null; priceCents: number; paymentStatus: string; publicationStatus: 'DRAFT' | 'PUBLISHED' | 'PAUSED' | 'CLOSED' | 'AWAITING_PAYMENT'; createdAt: string; updatedAt: string; views: number; applicationClicks: number; applications: number; isInternship: boolean; acceptedCourses: string | null; headcount: number | null; applicationDeadline: string | null; checkoutUrl: string | null };
type CompanyApplication = { id: number; listingId: number; listingTitle: string; kind: 'job' | 'course'; name: string; email: string; phone: string; message: string; status: 'RECEIVED' | 'IN_REVIEW' | 'CONTACTED' | 'ACCEPTED' | 'DECLINED'; createdAt: string };
type Member = { name: string; email: string; role: string; createdAt: string };
type Invite = { email: string; role: string; expiresAt: string; inviteUrl: string };
type CommercialInterest = { id: number; offerType: string; title: string; details: string; createdAt: string };
type AnalyticsDay = { date: string; views: number; clicks: number; applications: number };
type ListingAnalytics = { listingId: number; title: string; kind: 'job' | 'course'; views: number; clicks: number; applications: number };
type CompanyAnalytics = { days: number; daily: AnalyticsDay[]; listings: ListingAnalytics[] };
type ListingForm = { kind: 'job' | 'course'; title: string; area: string; description: string; requirements: string; location: string; modality: string; url: string; contactEmail: string; salary: string; contractType: string; workSchedule: string; workload: string; prerequisites: string; benefits: string; coursePrice: string; certificate: string; isInternship: boolean; acceptedCourses: string; headcount: string; applicationDeadline: string };
type CompanyPage = 'overview' | 'listings' | 'applications' | 'metrics' | 'growth' | 'profile' | 'team';
const companyPageFromHash = (): CompanyPage => ({ '#painel': 'overview', '#divulgacoes': 'listings', '#selecao': 'applications', '#crescimento': 'growth', '#perfil-publico': 'profile', '#equipe': 'team', '#empresa-visao-geral': 'overview', '#empresa-divulgacoes': 'listings', '#empresa-candidaturas': 'applications', '#empresa-metricas': 'metrics', '#empresa-planos': 'growth', '#empresa-perfil': 'profile', '#empresa-equipe': 'team' }[window.location.hash] as CompanyPage | undefined) || 'overview';
const companyPageHashes: Record<CompanyPage, string> = { overview: '#empresa-visao-geral', listings: '#empresa-divulgacoes', applications: '#empresa-candidaturas', metrics: '#empresa-metricas', growth: '#empresa-planos', profile: '#empresa-perfil', team: '#empresa-equipe' };
const emptyForm: ListingForm = { kind: 'job', title: '', area: '', description: '', requirements: '', location: '', modality: 'Presencial', url: '', contactEmail: '', salary: '', contractType: 'CLT', workSchedule: 'Integral', workload: '', prerequisites: '', benefits: '', coursePrice: '', certificate: '', isInternship: false, acceptedCourses: '', headcount: '', applicationDeadline: '' };
const field = 'mt-2 w-full rounded-xl border border-white/15 bg-[#0b1421] px-4 py-3 text-ink placeholder:text-ink/35';
const statusLabels: Record<Listing['publicationStatus'], string> = { DRAFT: 'Rascunho', PUBLISHED: 'Publicado', PAUSED: 'Pausado', CLOSED: 'Encerrado', AWAITING_PAYMENT: 'Aguardando pagamento' };
const roleLabels: Record<string, string> = { OWNER: 'Proprietário', RECRUITER: 'Recrutador', ANALYST: 'Analista' };

function summarizeFailures(failures: { area: string; message: string }[]) {
  if (failures.length === 0) return '';
  const areas = [...new Set(failures.map(failure => failure.area))];
  const details = [...new Set(failures.map(failure => failure.message))];
  return `Não foi possível carregar ${areas.join(', ')}. ${details.join(' ')}`;
}

export function CompanyDashboard({ token, onLogout }: { token: string; onLogout: () => void }) {
  const [page, setPage] = useState<CompanyPage>(companyPageFromHash);
  const [company, setCompany] = useState<Company | null>(null);
  const [listings, setListings] = useState<Listing[]>([]);
  const [applications, setApplications] = useState<CompanyApplication[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [teamLoaded, setTeamLoaded] = useState(false);
  const [invites, setInvites] = useState<Invite[]>([]);
  const [commercialInterests, setCommercialInterests] = useState<CommercialInterest[]>([]);
  const [analytics, setAnalytics] = useState<CompanyAnalytics | null>(null);
  const [analyticsDays, setAnalyticsDays] = useState<7 | 30 | 90>(30);
  const [analyticsLoading, setAnalyticsLoading] = useState(false);
  const [form, setForm] = useState<ListingForm>(emptyForm);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [profileForm, setProfileForm] = useState({ tradeName: '', industry: '', phone: '', website: '', city: '', state: '', description: '' });
  const [inviteForm, setInviteForm] = useState({ email: '', role: 'RECRUITER' });
  const [createdInvite, setCreatedInvite] = useState('');
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [showTeam, setShowTeam] = useState(false);
  const [applicationStatusFilter, setApplicationStatusFilter] = useState('ALL');
  const [applicationListingFilter, setApplicationListingFilter] = useState('ALL');
  const [commercialBusy, setCommercialBusy] = useState(false);
  const [partnershipForm, setPartnershipForm] = useState({ provider: '', courseUrl: '', enrollmentUrl: '', compensation: '' });
  const [promotionListingId, setPromotionListingId] = useState('');
  const normalizedRole = company?.role?.trim().toUpperCase();
  // Exibe o fluxo ao titular mesmo em contas antigas cujo papel veio vazio;
  // o servidor continua validando as permissões de cada operação.
  const canRecruit = normalizedRole !== 'ANALYST';
  const isOwner = normalizedRole === 'OWNER';

  useEffect(() => {
    const syncPage = () => setPage(companyPageFromHash());
    window.addEventListener('hashchange', syncPage);
    window.addEventListener('popstate', syncPage);
    return () => { window.removeEventListener('hashchange', syncPage); window.removeEventListener('popstate', syncPage); };
  }, []);

  useEffect(() => {
    if (page !== 'metrics') return;
    let active = true;
    setAnalyticsLoading(true); setError('');
    api<CompanyAnalytics>(`/company/analytics?days=${analyticsDays}`, token)
      .then(result => { if (active) setAnalytics(result); })
      .catch(cause => { if (active) setError(cause instanceof Error ? cause.message : 'Não foi possível carregar as métricas.'); })
      .finally(() => { if (active) setAnalyticsLoading(false); });
    return () => { active = false; };
  }, [page, analyticsDays, token]);

  function navigateCompanyPage(next: CompanyPage) {
    window.history.pushState(null, '', `${window.location.pathname}${window.location.search}${companyPageHashes[next]}`);
    setPage(next);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function openListingForm(kind: ListingForm['kind']) {
    setForm({ ...emptyForm, kind }); setEditingId(null); setShowForm(true); navigateCompanyPage('listings');
  }

  const refresh = useCallback(async () => {
    const companyData = await api<Company>('/company/dashboard', token);
    setCompany(companyData);
    setProfileForm({ tradeName: companyData.tradeName, industry: companyData.industry, phone: companyData.phone, website: companyData.website || '', city: companyData.city, state: companyData.state, description: companyData.description || '' });

    // Uma lista vazia é um resultado normal, não uma falha.
    const failures: { area: string; message: string }[] = [];
    const recordFailure = (area: string, cause: unknown, fallback: string) => {
      failures.push({ area, message: cause instanceof Error ? cause.message : fallback });
    };
    try { setCommercialInterests(await api<CommercialInterest[]>('/company/commercial-interests', token)); }
    catch (cause) { recordFailure('opções comerciais', cause, 'Não foi possível carregar as opções comerciais.'); }
    try {
      const companyListings = await api<Listing[]>('/company/listings', token);
      setListings(companyListings);
      if (companyData.role !== 'ANALYST' && companyListings.length > 0) {
        try { setApplications(await api<CompanyApplication[]>('/company/applications', token)); }
        catch (cause) { recordFailure('candidaturas', cause, 'Não foi possível carregar as candidaturas.'); }
      } else setApplications([]);
    } catch (cause) {
      recordFailure('vagas e cursos', cause, 'Não foi possível carregar as divulgações.');
      setApplications([]);
    }
    setError(summarizeFailures(failures));
  }, [token]);
  useEffect(() => {
    setLoading(true);
    refresh().catch(cause => setError(cause instanceof Error ? cause.message : 'Não foi possível carregar o painel empresarial.'))
      .finally(() => setLoading(false));
  }, [refresh]);

  async function toggleTeam() {
    const opening = !showTeam;
    setShowTeam(opening);
    if (!opening || teamLoaded) return;
    setError('');
    const failures: { area: string; message: string }[] = [];
    const [memberResult, inviteResult] = await Promise.allSettled([
      api<Member[]>('/company/members', token),
      api<Invite[]>('/company/invites', token),
    ]);
    if (memberResult.status === 'fulfilled') setMembers(memberResult.value);
    else failures.push({ area: 'equipe', message: memberResult.reason instanceof Error ? memberResult.reason.message : 'Não foi possível carregar a equipe.' });
    if (inviteResult.status === 'fulfilled') setInvites(inviteResult.value);
    else failures.push({ area: 'convites', message: inviteResult.reason instanceof Error ? inviteResult.reason.message : 'Não foi possível carregar os convites.' });
    if (failures.length === 0) setTeamLoaded(true);
    setError(summarizeFailures(failures));
  }

  async function submitListing(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(''); setNotice(''); setBusy(true);
    const wasEditing = editingId !== null;
    try {
      const payload = { ...form, contractType: form.isInternship ? 'Estágio' : form.contractType, headcount: form.headcount ? Number(form.headcount) : null, applicationDeadline: form.applicationDeadline || null };
      const saved = await api<Listing>(wasEditing ? `/company/listings/${editingId}` : '/company/listings', token, { method: wasEditing ? 'PUT' : 'POST', body: JSON.stringify(payload) });
      setListings(current => wasEditing ? current.map(item => item.id === saved.id ? saved : item) : [saved, ...current]);
      setForm(emptyForm); setEditingId(null); setShowForm(false);
      setNotice(wasEditing ? 'Alterações salvas.' : saved.isInternship ? 'Vaga de estágio salva. Revise os dados e inicie o pagamento de R$ 50,00 para publicá-la.' : 'Vaga ou curso cadastrado como rascunho. Você já pode publicar.');
      try { await refresh(); }
      catch (cause) { setError(cause instanceof Error ? `Cadastro salvo; não foi possível atualizar os dados exibidos: ${cause.message}` : 'Cadastro salvo; atualize a página para recarregar os dados.'); }
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível salvar o anúncio.'); }
    finally { setBusy(false); }
  }

  function editListing(item: Listing) {
    setForm({ kind: item.kind, title: item.title, area: item.area, description: item.description, requirements: item.requirements, location: item.location, modality: item.modality, url: item.url, contactEmail: item.contactEmail, salary: item.salary || '', contractType: item.contractType || '', workSchedule: item.workSchedule || '', workload: item.workload || '', prerequisites: item.prerequisites || '', benefits: item.benefits || '', coursePrice: item.coursePrice || '', certificate: item.certificate || '', isInternship: item.isInternship, acceptedCourses: item.acceptedCourses || '', headcount: item.headcount ? String(item.headcount) : '', applicationDeadline: item.applicationDeadline || '' });
    setEditingId(item.id); setShowForm(true); window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  async function startInternshipPayment(item: Listing) {
    setError(''); setNotice(''); setBusy(true);
    try {
      const checkout = await api<{ checkoutUrl: string | null; status: string }>(`/company/listings/${item.id}/payment`, token, { method: 'POST' });
      if (!checkout.checkoutUrl) throw new Error('O pagamento ainda está sendo confirmado. Atualize a página em instantes.');
      window.location.assign(checkout.checkoutUrl);
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível iniciar o pagamento.'); }
    finally { setBusy(false); }
  }

  async function setListingStatus(item: Listing, status: Listing['publicationStatus']) {
    setError(''); setNotice('');
    try { await api(`/company/listings/${item.id}/status`, token, { method: 'PUT', body: JSON.stringify({ status }) }); await refresh(); setNotice(`Anúncio atualizado para “${statusLabels[status]}”.`); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível atualizar o anúncio.'); }
  }

  async function renewListing(item: Listing) {
    const expiresAt = new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);
    try { await api(`/company/listings/${item.id}/renew`, token, { method: 'PUT', body: JSON.stringify({ expiresAt }) }); await refresh(); setNotice('Anúncio renovado por mais 30 dias.'); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível renovar o anúncio.'); }
  }

  async function saveProfile(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(''); setBusy(true);
    try { await api('/company/profile', token, { method: 'PUT', body: JSON.stringify(profileForm) }); await refresh(); setNotice('Perfil público atualizado.'); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível salvar o perfil.'); }
    finally { setBusy(false); }
  }

  async function inviteMember(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(''); setCreatedInvite('');
    try { const invite = await api<Invite>('/company/invites', token, { method: 'POST', body: JSON.stringify(inviteForm) }); setCreatedInvite(invite.inviteUrl); setInvites(await api<Invite[]>('/company/invites', token)); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível criar o convite.'); }
  }

  async function changeApplicationStatus(application: CompanyApplication, status: CompanyApplication['status']) {
    try { await api(`/company/applications/${application.id}/status`, token, { method: 'PUT', body: JSON.stringify({ status }) }); setApplications(await api<CompanyApplication[]>('/company/applications', token)); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível atualizar a candidatura.'); }
  }

  async function requestCommercialOffer(offerType: string, title: string, details: string): Promise<boolean> {
    setError(''); setNotice(''); setCommercialBusy(true);
    try {
      const saved = await api<CommercialInterest>('/company/commercial-interests', token, { method: 'POST', body: JSON.stringify({ offerType, title, details }) });
      setCommercialInterests(current => [saved, ...current]);
      setNotice('Interesse registrado. Esta é uma etapa de validação comercial: nenhum pagamento foi iniciado.');
      return true;
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível registrar o interesse.'); return false; }
    finally { setCommercialBusy(false); }
  }

  async function removeCommercialInterest(item: CommercialInterest) {
    if (!window.confirm(`Remover o registro “${item.title}” dos seus interesses comerciais?`)) return;
    setError('');
    try {
      await api<void>(`/company/commercial-interests/${item.id}`, token, { method: 'DELETE' });
      setCommercialInterests(current => current.filter(interest => interest.id !== item.id));
      setNotice('Registro removido dos seus interesses comerciais.');
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível remover este interesse.'); }
  }

  function exportApplications() {
    const headers = ['Oportunidade', 'Tipo', 'Candidato', 'E-mail', 'Telefone', 'Etapa', 'Recebida em', 'Mensagem'];
    const rows = filteredApplications.map(item => [item.listingTitle, item.kind === 'job' ? 'Vaga' : 'Curso', item.name, item.email, item.phone, item.status, new Date(item.createdAt).toLocaleDateString('pt-BR'), item.message]);
    const csv = [headers, ...rows].map(row => row.map(value => `"${String(value ?? '').replaceAll('"', '""')}"`).join(';')).join('\r\n');
    const url = URL.createObjectURL(new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a'); link.href = url; link.download = 'candidaturas-trampolim.csv'; link.click(); URL.revokeObjectURL(url);
  }

  const totalViews = listings.reduce((sum, item) => sum + item.views, 0);
  const totalClicks = listings.reduce((sum, item) => sum + item.applicationClicks, 0);
  const totalApplications = listings.reduce((sum, item) => sum + item.applications, 0);
  const filteredApplications = applications.filter(item => (applicationStatusFilter === 'ALL' || item.status === applicationStatusFilter) && (applicationListingFilter === 'ALL' || String(item.listingId) === applicationListingFilter));
  const analyticsTotals = analytics?.daily.reduce((totals, item) => ({ views: totals.views + item.views, clicks: totals.clicks + item.clicks, applications: totals.applications + item.applications }), { views: 0, clicks: 0, applications: 0 }) || { views: 0, clicks: 0, applications: 0 };
  const chartMax = Math.max(1, ...(analytics?.daily.flatMap(item => [item.views, item.clicks, item.applications]) || [1]));
  const chartPoints = (key: 'views' | 'clicks' | 'applications') => analytics?.daily.map((item, index) => `${analytics.daily.length <= 1 ? 300 : 16 + (index * 568 / (analytics.daily.length - 1))},${184 - (item[key] / chartMax) * 160}`).join(' ') || '';
  const percent = (value: number, base: number) => base ? `${(value / base * 100).toFixed(1).replace('.', ',')}%` : '—';

  return <><RibbonStrip /><header className="border-b border-white/10 px-[6vw] py-5"><div className="mx-auto flex max-w-7xl items-center justify-between"><a href="#painel" className="font-serif font-black text-[22px] tracking-[-0.5px] text-ink no-underline">Trampol<span className="text-brand-red">i</span>m <span className="ml-2 font-sans text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Empresas</span></a><div className="flex items-center gap-2"><a href="#inicio" className="hidden rounded-full border border-white/15 px-3 py-2 text-xs font-bold no-underline sm:inline-flex">Ecossistema</a><a href="#capacita" className="hidden rounded-full border border-white/15 px-3 py-2 text-xs font-bold no-underline sm:inline-flex">Capacita</a><span className="hidden text-sm text-ink/60 sm:inline">{company ? roleLabels[normalizedRole || ''] || 'Conta empresarial' : 'Portal empresarial'}</span><button onClick={onLogout} className="rounded-full border border-white/15 bg-transparent px-5 py-2 font-bold text-ink">Sair</button></div></div></header>
      <nav aria-label="Navegação empresarial" className="sticky top-0 z-30 border-b border-white/10 bg-[#0b1421]/95 px-0 py-3 backdrop-blur"><div className="mobile-nav-scroll mx-auto flex max-w-7xl gap-2 overflow-x-auto overscroll-x-contain px-[6vw] pb-1">
        {([['overview', 'Visão geral'], ['listings', 'Vagas e cursos'], ...(canRecruit ? [['applications', 'Candidaturas']] : []), ['metrics', 'Métricas'], ...(canRecruit ? [['growth', 'Planos e parcerias']] : []), ['profile', 'Perfil público'], ...(isOwner ? [['team', 'Equipe']] : [])] as [CompanyPage, string][]).map(([destination, label]) => <button key={destination} type="button" aria-current={page === destination ? 'page' : undefined} onClick={() => navigateCompanyPage(destination)} className={`min-h-11 shrink-0 whitespace-nowrap rounded-full border px-4 py-2 text-sm font-bold transition-colors ${page === destination ? 'border-ink bg-ink text-brand-white' : 'border-ink/15 bg-transparent text-ink hover:border-ink/40 hover:bg-paper'}`}>{label}</button>)}
      </div></nav>
    <main id="painel" className="mx-auto min-h-[calc(100vh-11rem)] w-full max-w-[1600px] px-[6vw] pb-10">
      {page === 'overview' && <>
      <section className="relative isolate left-1/2 min-h-[68vh] w-screen max-w-none -translate-x-1/2 overflow-hidden pb-20 pl-[6vw] pr-6 pt-10 md:pb-24 md:pt-14">
        <div aria-hidden="true" className="pointer-events-none absolute right-6 top-6 -z-10 h-[34rem] w-[34rem] rounded-full border border-brand-yellow/20 shadow-[0_0_120px_rgba(214,255,56,0.08)]" />
        <div className="grid w-full max-w-none items-center gap-10 lg:grid-cols-[1.08fr_0.92fr]">
          <div>
            <p className="mb-5 flex items-center gap-3 text-xs font-extrabold uppercase tracking-[0.22em] text-brand-yellow"><span className="h-px w-9 bg-brand-yellow" />Trampolim empresas · talentos · oportunidades</p>
            <h1 className="max-w-4xl text-[clamp(4rem,10vw,8.4rem)] font-extrabold uppercase leading-[0.82] tracking-[-0.04em]">Seu próximo<br />talento <span className="text-brand-yellow">começa</span><br />aqui.</h1>
            <p className="mt-8 max-w-xl text-base leading-7 text-ink/70 md:text-lg">Publique vagas e cursos, encontre novos talentos e acompanhe cada etapa da seleção em um só lugar.</p>
            {canRecruit && <div className="mt-8 flex flex-wrap gap-3">
              <button onClick={() => openListingForm('job')} className="rounded-full border-0 bg-brand-yellow px-6 py-3 font-extrabold text-[#101725]">Cadastrar vaga <span aria-hidden="true">↗</span></button>
              <button onClick={() => openListingForm('course')} className="rounded-full border border-white/35 bg-transparent px-6 py-3 font-extrabold text-white">Cadastrar curso</button>
            </div>}
            <div className="mt-10 flex flex-wrap items-center gap-x-6 gap-y-2 text-xs font-semibold text-ink/55"><span>✓ Divulgação de vagas e cursos</span><span>✓ Acompanhamento de candidaturas</span><span>✓ Gestão da equipe</span></div>
          </div>
          <div className="relative w-full">
            <div className="absolute inset-0 rounded-[2rem] border border-brand-yellow/20" aria-hidden="true" />
            <article className="relative overflow-hidden rounded-[1.8rem] border border-white/10 bg-[#101a29] p-6 shadow-2xl md:p-8">
              <div className="flex items-start justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-[0.2em] text-brand-yellow">Seu painel empresarial</p><h2 className="mt-2 text-3xl font-bold text-white md:text-4xl">Da sua empresa<br />ao próximo talento.</h2></div>{canRecruit && <button type="button" aria-label="Cadastrar uma vaga" onClick={() => openListingForm('job')} className="grid h-12 w-12 shrink-0 place-items-center rounded-full border-0 bg-brand-yellow text-2xl font-black text-[#101725]">↗</button>}</div>
              <div className="my-7 h-px bg-white/10" />
              <div className="space-y-5">
                {[['01', 'Publique oportunidades', 'Cadastre vagas e cursos com as informações completas.'], ['02', 'Acompanhe os resultados', 'Confira visualizações, inscrições e candidaturas.'], ['03', 'Organize sua equipe', 'Convide pessoas e acompanhe as etapas da seleção.']].map(([number, title, description], index) => <div key={number} className="flex gap-4"><span className={`shrink-0 font-serif text-2xl font-bold ${index === 0 ? 'text-brand-yellow' : 'text-white/35'}`}>{number}</span><div><h3 className="font-bold text-white">{title}</h3><p className="mt-1 text-sm leading-6 text-white/55">{description}</p></div></div>)}
              </div>
              <div className="mt-8 flex items-center justify-between rounded-2xl border border-brand-yellow/25 bg-brand-yellow/5 px-4 py-3"><span className="text-xs font-bold uppercase tracking-wider text-white/65">Um passo de cada vez</span><span className="text-sm font-extrabold text-brand-yellow">Sua empresa, seu ritmo</span></div>
            </article>
          </div>
        </div>
      </section>
      {company && <section className="grid gap-4 md:grid-cols-3"><div className="rounded-3xl border border-white/10 bg-[#121c2b] p-6 md:col-span-2"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Sua empresa</p><h2 className="mt-2 text-2xl font-black">{company.tradeName}</h2><p className="mt-1 text-sm text-ink/60">{company.legalName} · CNPJ {company.cnpj}</p><p className="mt-3 text-sm text-ink/70">{company.industry} · {company.city}/{company.state}</p><div className="mt-4 flex flex-wrap gap-3"><button onClick={() => navigateCompanyPage('profile')} className="rounded-full border border-white/20 px-4 py-2 text-sm font-bold">Editar perfil público</button><button onClick={() => navigateCompanyPage('listings')} className="rounded-full bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725]">Ver divulgações</button></div></div><div className="rounded-3xl border border-brand-yellow/20 bg-brand-yellow/5 p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Indicadores gerais</p><p className="mt-3 text-2xl font-black">{totalViews} visualizações</p><p className="mt-1 text-sm text-ink/60">{totalClicks} cliques · {totalApplications} candidaturas/inscrições</p><p className="mt-4 text-xs text-ink/55">Taxa de divulgação informativa: R$ 100 por anúncio. Pagamentos não são processados nesta fase.</p></div></section>}
      </>}
      {loading && <p role="status" className="mt-5 rounded-2xl border border-white/10 bg-[#121c2b] p-4 text-sm font-bold">Carregando dados da empresa…</p>}
      {error && <div role="alert" className="mt-5 rounded-2xl border border-red-400/30 bg-red-400/10 p-4 text-sm font-bold">{error}{!company && <button type="button" onClick={() => { setLoading(true); refresh().catch(cause => setError(cause instanceof Error ? cause.message : "Não foi possível carregar o painel empresarial." )).finally(() => setLoading(false)); }} className="ml-3 underline">Tentar novamente</button>}</div>}{notice && <p role="status" className="mt-5 rounded-2xl border border-brand-yellow/30 bg-brand-yellow/10 p-4 text-sm font-bold">{notice}</p>}

      {page === 'profile' && company && <section id="perfil-publico" className="mt-8 scroll-mt-24 rounded-3xl border border-white/10 bg-[#121c2b] p-6 md:p-9"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Perfil público</p><h2 className="mt-2 text-3xl font-black">Apresente sua empresa</h2><form onSubmit={saveProfile} className="mt-6 grid gap-4 md:grid-cols-2"><label className="text-sm font-bold">Nome público<input required value={profileForm.tradeName} onChange={e => setProfileForm({ ...profileForm, tradeName: e.target.value })} className={field} /></label><label className="text-sm font-bold">Setor<input required value={profileForm.industry} onChange={e => setProfileForm({ ...profileForm, industry: e.target.value })} className={field} /></label><label className="text-sm font-bold">Telefone<input required value={profileForm.phone} onChange={e => setProfileForm({ ...profileForm, phone: e.target.value })} className={field} placeholder="Telefone público" /></label><label className="text-sm font-bold">Site<input type="url" value={profileForm.website} onChange={e => setProfileForm({ ...profileForm, website: e.target.value })} className={field} placeholder="https://" /></label><label className="text-sm font-bold">Cidade<input required value={profileForm.city} onChange={e => setProfileForm({ ...profileForm, city: e.target.value })} className={field} /></label><label className="text-sm font-bold">UF<input required minLength={2} maxLength={2} value={profileForm.state} onChange={e => setProfileForm({ ...profileForm, state: e.target.value.toUpperCase() })} className={field} /></label><label className="text-sm font-bold md:col-span-2">Apresentação<textarea maxLength={2000} rows={4} value={profileForm.description} onChange={e => setProfileForm({ ...profileForm, description: e.target.value })} className={field} placeholder="Conte sobre a empresa, cultura e atuação." /></label><button disabled={busy} className="rounded-full border-0 bg-brand-yellow px-6 py-3 font-extrabold text-[#101725] md:col-span-2">Salvar perfil</button></form></section>}

      {page === 'listings' && showForm && <section id="formulario-divulgacao" className="mt-8 scroll-mt-24 rounded-3xl border border-white/10 bg-[#121c2b] p-6 md:p-9"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">{editingId ? 'Editar divulgação' : 'Nova divulgação'}</p><h2 className="mt-2 text-3xl font-black">Detalhes do {form.isInternship ? 'estágio' : form.kind === 'job' ? 'emprego' : 'curso'}</h2><p className="mt-2 text-sm text-ink/65">A divulgação de estágio custa R$ 50,00 por vaga. As demais modalidades mantêm as regras atuais.</p></div><button onClick={() => { setShowForm(false); setEditingId(null); }} className="rounded-full border border-white/15 bg-transparent px-4 py-2 font-bold text-ink">Fechar</button></div>
        <form onSubmit={submitListing} className="mt-7 grid gap-5 md:grid-cols-2"><label className="text-sm font-bold">Tipo<select disabled={Boolean(editingId)} value={form.kind} onChange={e => setForm({ ...form, kind: e.target.value as ListingForm['kind'] })} className={field}><option value="job">Vaga de emprego</option><option value="course">Curso</option></select></label><label className="text-sm font-bold">Título<input required maxLength={180} value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} className={field} /></label><label className="text-sm font-bold">Área profissional<input required value={form.area} onChange={e => setForm({ ...form, area: e.target.value })} className={field} /></label><label className="text-sm font-bold">Localidade<input required value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} className={field} /></label><label className="text-sm font-bold">Modalidade<select value={form.modality} onChange={e => setForm({ ...form, modality: e.target.value })} className={field}><option>Presencial</option><option>Híbrido</option><option>Remoto</option><option>Online</option></select></label><label className="text-sm font-bold">Link externo de candidatura ou matrícula (opcional)<input type="url" value={form.url} onChange={e => setForm({ ...form, url: e.target.value })} className={field} placeholder="https://" /></label><label className="text-sm font-bold md:col-span-2">Descrição<textarea required minLength={20} rows={4} value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} className={field} /></label><label className="text-sm font-bold md:col-span-2">Requisitos / público-alvo<textarea required rows={3} value={form.requirements} onChange={e => setForm({ ...form, requirements: e.target.value })} className={field} /></label>
          {form.kind === 'job' ? <><label className="flex items-start gap-3 rounded-2xl border border-brand-yellow/20 bg-brand-yellow/5 p-4 text-sm font-bold md:col-span-2"><input type="checkbox" checked={form.isInternship} disabled={Boolean(editingId)} onChange={e => setForm({ ...form, isInternship: e.target.checked, contractType: e.target.checked ? 'Estágio' : 'CLT' })} className="mt-1"/><span>Esta é uma vaga de estágio. A divulgação custa <strong>R$ 50,00</strong>, com pagamento confirmado pelo Mercado Pago antes da publicação.</span></label><label className="text-sm font-bold">{form.isInternship ? 'Bolsa-auxílio (opcional)' : 'Faixa salarial'}<input required={!form.isInternship} value={form.salary} onChange={e => setForm({ ...form, salary: e.target.value })} className={field} /></label>{form.isInternship ? <div className="text-sm font-bold">Tipo de contrato<span className={`${field} block`}>Estágio</span></div> : <label className="text-sm font-bold">Tipo de contrato<input required value={form.contractType} onChange={e => setForm({ ...form, contractType: e.target.value })} className={field} /></label>}<label className="text-sm font-bold">Jornada{form.isInternship ? ' (opcional)' : ''}<input required={!form.isInternship} value={form.workSchedule} onChange={e => setForm({ ...form, workSchedule: e.target.value })} className={field} /></label><label className="text-sm font-bold">Benefícios (opcional)<input value={form.benefits} onChange={e => setForm({ ...form, benefits: e.target.value })} className={field} /></label>{form.isInternship && <><label className="text-sm font-bold">Cursos/formações aceitos (opcional)<input maxLength={1000} value={form.acceptedCourses} onChange={e => setForm({ ...form, acceptedCourses: e.target.value })} className={field} placeholder="Ex.: Administração, Sistemas de Informação" /></label><label className="text-sm font-bold">Quantidade de vagas (opcional)<input type="number" min={1} max={999} value={form.headcount} onChange={e => setForm({ ...form, headcount: e.target.value })} className={field} /></label><label className="text-sm font-bold">Prazo de inscrição (opcional)<input type="date" min={new Date().toISOString().slice(0, 10)} value={form.applicationDeadline} onChange={e => setForm({ ...form, applicationDeadline: e.target.value })} className={field} /><span className="mt-1 block text-xs font-normal text-ink/50">Se não informar, a vaga ficará aberta por 30 dias.</span></label></>}</> : <><label className="text-sm font-bold">Carga horária<input required value={form.workload} onChange={e => setForm({ ...form, workload: e.target.value })} className={field} /></label><label className="text-sm font-bold">Pré-requisitos<input required value={form.prerequisites} onChange={e => setForm({ ...form, prerequisites: e.target.value })} className={field} /></label><label className="text-sm font-bold">Investimento<input value={form.coursePrice} onChange={e => setForm({ ...form, coursePrice: e.target.value })} className={field} /></label><label className="text-sm font-bold">Certificado<input value={form.certificate} onChange={e => setForm({ ...form, certificate: e.target.value })} className={field} /></label></>}
          <label className="text-sm font-bold md:col-span-2">E-mail de contato<input required type="email" value={form.contactEmail} onChange={e => setForm({ ...form, contactEmail: e.target.value })} className={field} /></label><button disabled={busy} className="rounded-full border-0 bg-brand-yellow px-7 py-4 font-extrabold text-[#101725] disabled:opacity-60 md:col-span-2">{busy ? 'Salvando…' : editingId ? 'Salvar alterações' : 'Salvar como rascunho'}</button></form></section>}

      {page === 'listings' && <section id="divulgacoes" className="mt-10 scroll-mt-24"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Gestão</p><h2 className="mt-2 text-3xl font-black">Minhas divulgações</h2><p className="mt-1 text-sm text-ink/60">Gerencie vagas de emprego e cursos publicados pela sua empresa.</p></div><div className="flex items-center gap-3"><span className="rounded-full bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725]">{listings.length} anúncios</span>{canRecruit && <button onClick={() => openListingForm('job')} className="rounded-full border-0 bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725]">+ Nova divulgação</button>}</div></div>
        {listings.length ? <div className="mt-5 grid gap-4 xl:grid-cols-2">{listings.map(item => <article key={item.id} className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><div className="flex flex-wrap items-center justify-between gap-3"><span className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">{item.isInternship ? 'Estágio · R$ 50,00' : item.kind === 'job' ? 'Vaga' : 'Curso'} · {item.area}</span><span className="rounded-full bg-brand-yellow/10 px-3 py-1 text-xs font-bold text-brand-yellow">{statusLabels[item.publicationStatus]}</span></div><h3 className="mt-3 text-2xl font-black">{item.title}</h3><p className="mt-2 text-sm text-ink/65">{item.location} · {item.modality}{item.expiresAt ? ` · Até ${new Date(`${item.expiresAt}T12:00:00`).toLocaleDateString('pt-BR')}` : ''}</p><div className="mt-4 grid grid-cols-3 gap-2 text-center"><div className="rounded-xl bg-[#0b1421] p-3"><strong className="block text-xl">{item.views}</strong><span className="text-xs text-ink/60">visualizações</span></div><div className="rounded-xl bg-[#0b1421] p-3"><strong className="block text-xl">{item.applicationClicks}</strong><span className="text-xs text-ink/60">cliques</span></div><div className="rounded-xl bg-[#0b1421] p-3"><strong className="block text-xl">{item.applications}</strong><span className="text-xs text-ink/60">inscrições</span></div></div><div className="mt-4 flex flex-wrap gap-2">{canRecruit && item.isInternship && item.paymentStatus !== 'PAID' && <button disabled={busy} onClick={() => void startInternshipPayment(item)} className='rounded-full bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725] disabled:opacity-50'>Pagar R$ 50,00</button>}{canRecruit && <button onClick={() => editListing(item)} className="rounded-full border border-white/15 px-4 py-2 text-sm font-bold">Editar</button>}{canRecruit && item.publicationStatus !== 'PUBLISHED' && (!item.isInternship || item.paymentStatus === 'PAID') && <button onClick={() => setListingStatus(item, 'PUBLISHED')} className="rounded-full bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725]">Publicar</button>}{canRecruit && item.publicationStatus === 'PUBLISHED' && <button onClick={() => setListingStatus(item, 'PAUSED')} className="rounded-full border border-white/15 px-4 py-2 text-sm font-bold">Pausar</button>}{canRecruit && item.publicationStatus !== 'CLOSED' && <button onClick={() => setListingStatus(item, 'CLOSED')} className="rounded-full border border-white/15 px-4 py-2 text-sm font-bold">Encerrar</button>}{canRecruit && !item.isInternship && (item.publicationStatus === 'CLOSED' || (item.expiresAt && item.expiresAt < new Date().toISOString().slice(0, 10))) && <button onClick={() => renewListing(item)} className="rounded-full border border-brand-yellow/30 px-4 py-2 text-sm font-bold text-brand-yellow">Renovar 30 dias</button>}{item.publicationStatus === 'PUBLISHED' && <a href={`/?empresa=${encodeURIComponent(company?.publicSlug || '')}`} target="_blank" rel="noreferrer" className="rounded-full border border-white/15 px-4 py-2 text-sm font-bold no-underline">Ver página</a>}</div></article>)}</div> : <div className="mt-5 rounded-3xl border border-dashed border-white/15 p-10 text-center"><h3 className="text-xl font-bold">Nenhuma divulgação por aqui ainda</h3><p className="mt-2 text-sm text-ink/60">Cadastre uma vaga ou curso para começar.</p></div>}
      </section>}

      {page === 'applications' && company?.role !== 'ANALYST' && <section id="selecao" className="mt-12 scroll-mt-24"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Seleção</p><h2 className="mt-2 text-3xl font-black">Candidaturas e inscrições</h2><p className="mt-1 text-sm text-ink/60">Acompanhe e organize as pessoas interessadas nas suas oportunidades.</p></div>{applications.length > 0 && <button type="button" onClick={exportApplications} className="rounded-full border border-white/20 px-4 py-2 text-sm font-bold">Exportar lista CSV</button>}</div>{applications.length > 0 && <div className="mt-5 flex flex-wrap gap-3"><label className="text-sm font-bold">Etapa<select value={applicationStatusFilter} onChange={e => setApplicationStatusFilter(e.target.value)} className={`${field} min-w-44`}><option value="ALL">Todas</option><option value="RECEIVED">Recebidas</option><option value="IN_REVIEW">Em análise</option><option value="CONTACTED">Contatadas</option><option value="ACCEPTED">Selecionadas</option><option value="DECLINED">Encerradas</option></select></label><label className="text-sm font-bold">Oportunidade<select value={applicationListingFilter} onChange={e => setApplicationListingFilter(e.target.value)} className={`${field} min-w-56`}><option value="ALL">Todas</option>{listings.map(listing => <option key={listing.id} value={listing.id}>{listing.title}</option>)}</select></label><span className="self-end rounded-xl bg-brand-yellow/10 px-4 py-3 text-sm font-bold text-brand-yellow">{filteredApplications.length} de {applications.length} registros</span></div>}{filteredApplications.length ? <div className="mt-5 space-y-3">{filteredApplications.map(item => <article key={item.id} className="rounded-2xl border border-white/10 bg-[#121c2b] p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase text-brand-yellow">{item.kind === 'job' ? 'Candidatura' : 'Inscrição'} · {item.listingTitle}</p><h3 className="mt-1 text-xl font-extrabold">{item.name}</h3><p className="text-sm text-ink/65">{item.email}{item.phone && ` · ${item.phone}`}</p>{item.message && <p className="mt-3 text-sm text-ink/75">{item.message}</p>}</div><select aria-label={`Etapa da candidatura de ${item.name}`} value={item.status} onChange={e => changeApplicationStatus(item, e.target.value as CompanyApplication['status'])} className="rounded-xl border border-white/15 bg-[#0b1421] px-3 py-2"><option value="RECEIVED">Recebida</option><option value="IN_REVIEW">Em análise</option><option value="CONTACTED">Contatada</option><option value="ACCEPTED">Selecionada</option><option value="DECLINED">Encerrada</option></select></div></article>)}</div> : <p className="mt-4 rounded-2xl border border-dashed border-white/15 p-6 text-sm text-ink/60">{applications.length ? 'Nenhuma candidatura corresponde aos filtros.' : 'As candidaturas e inscrições recebidas aparecerão aqui.'}</p>}</section>}

      {page === 'metrics' && <section className="mt-10 scroll-mt-24"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Inteligência da empresa</p><h2 className="mt-2 text-3xl font-black">Métricas e alcance</h2><p className="mt-2 max-w-2xl text-sm text-ink/65">Veja como as pessoas encontram suas oportunidades e avançam até a candidatura ou inscrição.</p></div><label className="text-sm font-bold">Período<select value={analyticsDays} onChange={event => setAnalyticsDays(Number(event.target.value) as 7 | 30 | 90)} className={`${field} min-w-40`}><option value={7}>Últimos 7 dias</option><option value={30}>Últimos 30 dias</option><option value={90}>Últimos 90 dias</option></select></label></div>
        <div className="mt-5 flex items-center gap-2 rounded-2xl border border-brand-yellow/25 bg-brand-yellow/5 p-4 text-sm"><span className="rounded-full bg-brand-yellow px-3 py-1 text-xs font-extrabold text-[#101725]">PILOTO</span><p>Insights avançados liberados para avaliação. O plano futuro de R$ 9,90/mês é apenas uma proposta; não há cobrança nesta etapa.</p></div>
        {analyticsLoading && <p role="status" className="mt-5 rounded-2xl border border-white/10 bg-[#121c2b] p-4">Carregando métricas…</p>}
        {!analyticsLoading && analytics && <>
          <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-5"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Alcance</p><strong className="mt-3 block text-3xl">{analyticsTotals.views}</strong><p className="mt-1 text-sm text-ink/55">vezes que anúncios entraram em tela</p></article><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-5"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Acessos</p><strong className="mt-3 block text-3xl">{analyticsTotals.clicks}</strong><p className="mt-1 text-sm text-ink/55">cliques em candidatura ou inscrição</p></article><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-5"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Conversões</p><strong className="mt-3 block text-3xl">{analyticsTotals.applications}</strong><p className="mt-1 text-sm text-ink/55">candidaturas e inscrições recebidas</p></article><article className="rounded-3xl border border-brand-yellow/25 bg-brand-yellow/5 p-5"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Alcance → candidatura</p><strong className="mt-3 block text-3xl">{percent(analyticsTotals.applications, analyticsTotals.views)}</strong><p className="mt-1 text-sm text-ink/55">taxa de conversão no período</p></article></div>
          <div className="mt-5 grid gap-4 xl:grid-cols-[1.4fr_0.6fr]"><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-5 md:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="text-xl font-black">Desempenho ao longo do tempo</h3><p className="mt-1 text-sm text-ink/55">Alcance, cliques e candidaturas por dia</p></div><div className="flex flex-wrap gap-3 text-xs font-bold"><span className="text-brand-yellow">● Alcance</span><span className="text-sky-300">● Cliques</span><span className="text-emerald-300">● Candidaturas</span></div></div><div className="mt-5 overflow-x-auto"><svg role="img" aria-label={`Gráfico de alcance, cliques e candidaturas nos últimos ${analytics.days} dias`} viewBox="0 0 600 200" className="h-56 min-w-[560px] w-full"><line x1="16" y1="184" x2="584" y2="184" stroke="rgba(255,255,255,.18)"/><line x1="16" y1="104" x2="584" y2="104" stroke="rgba(255,255,255,.08)"/><line x1="16" y1="24" x2="584" y2="24" stroke="rgba(255,255,255,.08)"/><polyline points={chartPoints('views')} fill="none" stroke="#d6ff38" strokeWidth="3" strokeLinejoin="round" strokeLinecap="round"/><polyline points={chartPoints('clicks')} fill="none" stroke="#7dd3fc" strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/><polyline points={chartPoints('applications')} fill="none" stroke="#6ee7b7" strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/></svg></div><div className="flex justify-between text-xs text-ink/45"><span>{analytics.daily[0] ? new Date(`${analytics.daily[0].date}T12:00:00`).toLocaleDateString('pt-BR') : ''}</span><span>Hoje</span></div></article>
            <article className="rounded-3xl border border-brand-yellow/20 bg-brand-yellow/5 p-5 md:p-7"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Leitura do período</p><h3 className="mt-2 text-xl font-black">Próximo passo</h3>{analyticsTotals.views === 0 ? <p className="mt-3 text-sm leading-6 text-ink/65">Quando seus anúncios começarem a aparecer para candidatos, você verá aqui como o alcance evolui.</p> : analyticsTotals.clicks === 0 ? <p className="mt-3 text-sm leading-6 text-ink/65">Há alcance, mas ainda não houve cliques. Experimente deixar o título, a faixa salarial ou os detalhes da oportunidade mais claros.</p> : analyticsTotals.applications === 0 ? <p className="mt-3 text-sm leading-6 text-ink/65">As pessoas estão acessando as oportunidades. Confira se os requisitos e as instruções de candidatura estão objetivos.</p> : <p className="mt-3 text-sm leading-6 text-ink/65">Você recebeu {analyticsTotals.applications} candidaturas ou inscrições. Compare os anúncios abaixo para identificar os que mais atraem candidatos.</p>}<div className="mt-5 space-y-3"><div className="flex justify-between gap-3 text-sm"><span className="text-ink/60">Alcance → clique</span><strong>{percent(analyticsTotals.clicks, analyticsTotals.views)}</strong></div><div className="h-2 rounded-full bg-white/10"><div className="h-full rounded-full bg-sky-300" style={{ width: `${Math.min(100, analyticsTotals.views ? analyticsTotals.clicks / analyticsTotals.views * 100 : 0)}%` }} /></div><div className="flex justify-between gap-3 text-sm"><span className="text-ink/60">Clique → candidatura</span><strong>{percent(analyticsTotals.applications, analyticsTotals.clicks)}</strong></div><div className="h-2 rounded-full bg-white/10"><div className="h-full rounded-full bg-emerald-300" style={{ width: `${Math.min(100, analyticsTotals.clicks ? analyticsTotals.applications / analyticsTotals.clicks * 100 : 0)}%` }} /></div></div></article></div>
          <section className="mt-5 rounded-3xl border border-white/10 bg-[#121c2b] p-5 md:p-7"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Comparativo</p><h3 className="mt-2 text-xl font-black">Desempenho por oportunidade</h3></div><span className="text-sm text-ink/55">Últimos {analytics.days} dias</span></div>{analytics.listings.length ? <div className="mt-4 space-y-3">{analytics.listings.map(item => <article key={item.listingId} className="rounded-2xl bg-[#0b1421] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-brand-yellow">{item.kind === 'job' ? 'Vaga' : 'Curso'}</p><h4 className="mt-1 font-extrabold">{item.title}</h4></div><div className="grid grid-cols-3 gap-3 text-right text-xs sm:gap-6"><span><strong className="block text-base">{item.views}</strong>alcance</span><span><strong className="block text-base">{item.clicks}</strong>cliques</span><span><strong className="block text-base">{item.applications}</strong>inscrições</span></div></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-brand-yellow" style={{ width: `${Math.max(1, Math.min(100, item.views ? item.applications / item.views * 100 : 0))}%` }} /></div><p className="mt-2 text-xs text-ink/50">Conversão de alcance para candidatura: {percent(item.applications, item.views)}</p></article>)}</div> : <p className="mt-4 rounded-2xl border border-dashed border-white/15 p-6 text-sm text-ink/60">Cadastre e publique uma oportunidade para acompanhar os resultados.</p>}</section>
          {canRecruit && <article className="mt-5 flex flex-wrap items-center justify-between gap-4 rounded-3xl border border-brand-yellow/25 bg-brand-yellow/5 p-5 md:p-7"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Plano Insights</p><h3 className="mt-2 text-xl font-black">Relatórios avançados por R$ 9,90/mês</h3><p className="mt-1 text-sm text-ink/60">Preço proposto para validar a ideia. O painel completo está liberado durante o piloto e não há cobrança real.</p></div><button disabled={commercialBusy} onClick={() => requestCommercialOffer('ANALYTICS', 'Plano Insights — R$ 9,90/mês', 'Interesse em relatórios avançados de alcance, conversão e desempenho. Preço proposto em validação; sem cobrança no piloto.')} className="rounded-full bg-brand-yellow px-5 py-3 text-sm font-extrabold text-[#101725] disabled:opacity-50">Quero participar do piloto</button></article>}
          <p className="mt-4 text-xs text-ink/45">Uma visualização é contada quando pelo menos metade do cartão do anúncio aparece na tela. Os relatórios mostram dados agregados e não identificam visitantes.</p>
        </>}</section>}

      {page === 'growth' && canRecruit && <section id="crescimento" className="mt-12 scroll-mt-24"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Novas oportunidades de negócio</p><h2 className="mt-2 text-3xl font-black">Faça mais com o Trampolim</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-ink/65">Registre interesse para conversarmos sobre ofertas piloto. Os valores abaixo são propostas para validação; nenhum pagamento é cobrado nesta etapa.</p>
        <div className="mt-6 grid gap-4 lg:grid-cols-3"><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Anúncio avulso</p><h3 className="mt-3 text-2xl font-black">R$ 100 <span className="text-sm font-semibold text-ink/60">por divulgação</span></h3><p className="mt-2 text-sm text-ink/65">A opção atual, sem compromisso recorrente.</p><p className="mt-4 text-xs text-ink/50">Preço informativo durante os testes; nenhum pagamento será iniciado.</p><button disabled={commercialBusy} onClick={() => requestCommercialOffer('PLAN', 'Anúncio avulso — R$ 100', 'Interesse na opção avulsa de R$ 100 por divulgação. Preço informativo; sem cobrança nesta etapa.')} className="mt-5 rounded-full border border-white/25 px-5 py-3 text-sm font-extrabold disabled:opacity-50">Selecionar anúncio avulso</button></article>
          <article className="rounded-3xl border border-brand-yellow/30 bg-brand-yellow/5 p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Pacote crescimento</p><h3 className="mt-3 text-2xl font-black">5 anúncios · R$ 450</h3><p className="mt-2 text-sm text-ink/65">R$ 90 por anúncio no pacote. Para empresas com várias oportunidades.</p><button disabled={commercialBusy} onClick={() => requestCommercialOffer('PLAN', 'Pacote Crescimento — 5 anúncios', 'Preço proposto de R$ 450, sujeito a validação. Sem cobrança nesta etapa.')} className="mt-5 rounded-full bg-brand-yellow px-5 py-3 text-sm font-extrabold text-[#101725] disabled:opacity-50">Tenho interesse</button></article>
          <article className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Pacote escala</p><h3 className="mt-3 text-2xl font-black">10 anúncios · R$ 800</h3><p className="mt-2 text-sm text-ink/65">R$ 80 por anúncio no pacote. Para processos contínuos de contratação e formação.</p><button disabled={commercialBusy} onClick={() => requestCommercialOffer('PLAN', 'Pacote Escala — 10 anúncios', 'Preço proposto de R$ 800, sujeito a validação. Sem cobrança nesta etapa.')} className="mt-5 rounded-full border border-white/25 px-5 py-3 text-sm font-extrabold disabled:opacity-50">Tenho interesse</button></article></div>
        <div className="mt-4 grid gap-4 lg:grid-cols-2"><article className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Mais visibilidade</p><h3 className="mt-2 text-xl font-black">Destaque por 7 dias · adicional proposto de R$ 30</h3><p className="mt-2 text-sm text-ink/65">Selecione uma oportunidade para registrar interesse no teste de divulgação prioritária.</p>{listings.length ? <div className="mt-4 flex flex-wrap gap-3"><select aria-label="Oportunidade para destaque" value={promotionListingId} onChange={e => setPromotionListingId(e.target.value)} className="min-w-52 flex-1 rounded-xl border border-white/15 bg-[#0b1421] px-4 py-3"><option value="">Selecione uma oportunidade</option>{listings.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select><button disabled={!promotionListingId || commercialBusy} onClick={() => { const item = listings.find(listing => String(listing.id) === promotionListingId); if (item) void requestCommercialOffer('HIGHLIGHT', `Destaque: ${item.title}`, `Anúncio ${item.id}. Adicional proposto de R$ 30 por 7 dias, sujeito a validação. Sem cobrança nesta etapa.`); }} className="rounded-full bg-brand-yellow px-5 py-3 text-sm font-extrabold text-[#101725] disabled:opacity-50">Registrar interesse</button></div> : <div className="mt-4"><p className="text-sm text-ink/55">Cadastre uma vaga ou curso para solicitar o destaque.</p><button type="button" onClick={() => openListingForm('job')} className="mt-3 rounded-full bg-brand-yellow px-5 py-3 text-sm font-extrabold text-[#101725]">+ Cadastrar vaga ou curso</button></div>}</article>
          <article className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Seleção assistida</p><h3 className="mt-2 text-xl font-black">Triagem e organização de candidatos</h3><p className="mt-2 text-sm text-ink/65">Estamos validando serviços de apoio para organizar etapas e encontrar perfis aderentes. Registre interesse para conversar sobre um piloto.</p><button disabled={commercialBusy} onClick={() => requestCommercialOffer('RECRUITMENT', 'Seleção assistida', 'Interesse em triagem e organização de etapas de seleção.')} className="mt-4 rounded-full border border-white/25 px-5 py-3 text-sm font-extrabold disabled:opacity-50">Quero conhecer o piloto</button></article></div>
        <div className="mt-4 grid gap-4 lg:grid-cols-2"><form onSubmit={event => { event.preventDefault(); const details = `Instituição: ${partnershipForm.provider}\nPágina do curso: ${partnershipForm.courseUrl}\nLink de matrícula/rastreamento: ${partnershipForm.enrollmentUrl || 'A definir'}\nModelo de remuneração: ${partnershipForm.compensation || 'A definir com o parceiro'}`; void requestCommercialOffer('COURSE_PARTNERSHIP', `Parceria de cursos — ${partnershipForm.provider}`, details).then(saved => { if (saved) setPartnershipForm({ provider: '', courseUrl: '', enrollmentUrl: '', compensation: '' }); }); }} className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Cursos parceiros</p><h3 className="mt-2 text-xl font-black">Indique uma parceria de formação</h3><div className="mt-4 grid gap-3"><label className="text-sm font-bold">Instituição<input required maxLength={160} value={partnershipForm.provider} onChange={e => setPartnershipForm({ ...partnershipForm, provider: e.target.value })} className={field} /></label><label className="text-sm font-bold">Página do curso<input required type="url" placeholder="https://" value={partnershipForm.courseUrl} onChange={e => setPartnershipForm({ ...partnershipForm, courseUrl: e.target.value })} className={field} /></label><label className="text-sm font-bold">Link de matrícula rastreável (opcional)<input type="url" placeholder="https://" value={partnershipForm.enrollmentUrl} onChange={e => setPartnershipForm({ ...partnershipForm, enrollmentUrl: e.target.value })} className={field} /></label><label className="text-sm font-bold">Comissão ou modelo de parceria (opcional)<input maxLength={200} value={partnershipForm.compensation} onChange={e => setPartnershipForm({ ...partnershipForm, compensation: e.target.value })} className={field} placeholder="A definir com a instituição" /></label><button disabled={commercialBusy} className="mt-1 w-fit rounded-full bg-brand-yellow px-5 py-3 text-sm font-extrabold text-[#101725] disabled:opacity-50">Enviar proposta</button></div></form>
          <article className="rounded-3xl border border-white/10 bg-[#121c2b] p-6"><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Parcerias institucionais</p><h3 className="mt-2 text-xl font-black">Conecte formação e trabalho na sua região</h3><p className="mt-2 text-sm text-ink/65">Escolas, organizações sociais e programas de aprendizagem podem aproximar empresas e talentos.</p><button disabled={commercialBusy} onClick={() => requestCommercialOffer('INSTITUTIONAL', 'Parceria institucional', 'Interesse em parceria regional com escolas, organizações sociais ou programas de aprendizagem.')} className="mt-4 rounded-full border border-white/25 px-5 py-3 text-sm font-extrabold disabled:opacity-50">Registrar interesse</button><p className="mt-4 text-xs text-ink/50">Parcerias de aprendizagem devem envolver instituições qualificadas.</p></article></div>
        {commercialInterests.length > 0 && <div className="mt-6 rounded-3xl border border-white/10 bg-[#121c2b] p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Acompanhamento</p><h3 className="mt-2 text-xl font-black">Seus interesses comerciais</h3></div><span className="rounded-full bg-brand-yellow px-4 py-2 text-sm font-extrabold text-[#101725]">{commercialInterests.length} registros</span></div><div className="mt-4 space-y-3">{commercialInterests.map(item => <article key={item.id} className="rounded-2xl bg-[#0b1421] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><h4 className="font-extrabold">{item.title}</h4><div className="flex items-center gap-3"><time className="text-xs text-ink/50">{new Date(item.createdAt).toLocaleDateString('pt-BR')}</time><button type="button" onClick={() => removeCommercialInterest(item)} className="rounded-full border border-red-300/30 px-3 py-1.5 text-xs font-bold text-red-200 transition-colors hover:bg-red-300/10">Remover</button></div></div><p className="mt-1 whitespace-pre-line text-sm text-ink/65">{item.details}</p><p className="mt-2 text-xs font-bold text-brand-yellow">Interesse registrado · sem cobrança</p></article>)}</div></div>}</section>}

      {page === 'team' && isOwner && <section id="equipe" className="mt-12 scroll-mt-24 rounded-3xl border border-white/10 bg-[#121c2b] p-6 md:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-widest text-brand-yellow">Acessos</p><h2 className="mt-2 text-3xl font-black">Equipe da empresa</h2><p className="mt-1 text-sm text-ink/60">Convide recrutadores e analistas com permissões diferentes.</p></div><button onClick={toggleTeam} className="rounded-full border border-white/15 px-4 py-2 font-bold">{showTeam ? 'Fechar' : teamLoaded ? `${members.length} membros` : 'Abrir equipe'}</button></div>{showTeam && <><div className="mt-5 grid gap-3 md:grid-cols-2">{members.map(member => <div key={member.email} className="rounded-2xl bg-[#0b1421] p-4"><p className="font-extrabold">{member.name}</p><p className="text-sm text-ink/60">{member.email} · {roleLabels[member.role] || member.role}</p></div>)}</div><form onSubmit={inviteMember} className="mt-6 grid gap-3 md:grid-cols-[1fr_220px_auto]"><label className="text-sm font-bold">E-mail da pessoa<input required type="email" value={inviteForm.email} onChange={e => setInviteForm({ ...inviteForm, email: e.target.value })} className={field} /></label><label className="text-sm font-bold">Acesso<select value={inviteForm.role} onChange={e => setInviteForm({ ...inviteForm, role: e.target.value })} className={field}><option value="RECRUITER">Recrutador</option><option value="ANALYST">Analista</option></select></label><button className="self-end rounded-full bg-brand-yellow px-5 py-3 font-extrabold text-[#101725]">Criar convite</button></form>{createdInvite && <div className="mt-4 rounded-2xl border border-brand-yellow/20 bg-brand-yellow/5 p-4"><p className="text-sm font-bold">Envie este link à pessoa convidada. Ele vale por 7 dias e só pode ser usado pelo e-mail informado.</p><input readOnly value={createdInvite} onFocus={e => e.currentTarget.select()} className={field} /><button onClick={() => navigator.clipboard.writeText(createdInvite).then(() => setNotice('Convite copiado.'))} className="mt-2 rounded-full border border-white/20 px-4 py-2 text-sm font-bold">Copiar convite</button></div>}{invites.length > 0 && <p className="mt-4 text-sm text-ink/60">{invites.length} convite(s) aguardando aceitação.</p>}</>}</section>}
    </main><footer className="mt-16 border-t border-white/10 px-[6vw] py-7"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 text-xs text-ink/55"><strong className="font-serif text-lg font-extrabold text-ink">TRAMPOLIM <span className="text-brand-yellow">EMPRESAS</span></strong><span>Gestão de talentos e oportunidades em um só lugar.</span><span>© {new Date().getFullYear()} Trampolim</span></div></footer></>;
}
